update artworks set status='Customer approved';
select pg_temp.fails('marketing: cannot lock artwork',$$update artworks set status='Locked'$$);
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',false); set role authenticated;
update artworks set status='Locked',locked=true;
select pg_temp.fails('md: locked artwork cannot be edited',$$update artworks set file_ref='hack.pdf'$$);
-- orders: marketing enters PO, cannot release; md releases -> ORD number
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000003',false); set role authenticated;
insert into orders(enquiry_id,customer_id,sku_id,owner_id,po_no,po_qty,po_price) select e.id,e.customer_id,s.id,e.owner_id,'PO-RLS',5000,155 from enquiries e, skus s where e.product='RLS test pouch' and s.sku_code='RLS-SKU';
select pg_temp.fails('marketing: cannot release order',$$update orders set released=true, confirmed_date=current_date+10$$);
select pg_temp.ok('marketing: order still unreleased',(select not released from orders where po_no='PO-RLS'));
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',false); set role authenticated;
select pg_temp.fails('md: release without confirmed date blocked',$$update orders set released=true where po_no='PO-RLS'$$);
update orders set released=true, confirmed_date=current_date+10, released_at=now() where po_no='PO-RLS';
select pg_temp.ok('md: release assigns ORD number',(select order_no ~ '^ORD-\d{4}-\d{4}$' from orders where po_no='PO-RLS'));
insert into order_stages(order_id,seq,name,dept_role) select id,1,'Material planning','planning' from orders where po_no='PO-RLS';
insert into order_stages(order_id,seq,name,dept_role) select id,2,'Printing','factory_manager' from orders where po_no='PO-RLS';
insert into order_stages(order_id,seq,name,dept_role) select id,3,'Packing','dispatch' from orders where po_no='PO-RLS';
-- departments update only their own stages
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000006',false); set role authenticated;
update order_stages set status='Done' where name='Material planning';
update order_stages set status='Done' where name='Printing';
select pg_temp.ok('planning: updated own stage',(select status from order_stages where name='Material planning')='Done');
select pg_temp.ok('planning: factory stage untouched',(select status from order_stages where name='Printing')='Pending');
select pg_temp.fails('planning: Delayed needs reason/recovery/revised date',$$update order_stages set status='Delayed' where name='Material planning'$$);
select pg_temp.fails('planning: cannot edit customers',$$insert into customers(name,mobile) values('x','1')$$);
select pg_temp.ok('planning: costing hidden',(select count(*) from costings)=0);
-- dispatch: dispatch + invoice; executive sees own invoice only
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000007',false); set role authenticated;
insert into invoices(invoice_no,customer_id,order_id,amount,due_date,exec_id) select 'INV-RLS',customer_id,id,300000,current_date+30,owner_id from orders where po_no='PO-RLS';
insert into dispatches(order_id,qty,date,invoice_no) select id,2000,current_date,'INV-RLS' from orders where po_no='PO-RLS';
update order_stages set status='Done' where name='Packing';
